import type { Slot } from './config';

/**
 * Catalogue items that look the same as an earlier item in their category (even after the
 * user picks their own colour), so the editor doesn't show them. They stay in the catalogue
 * — ids never shift — so avatars already wearing one still render it.
 *
 * Generated by the duplicate checker: `npx vite --config vite.avatar-test.config.ts`, then
 * open `?dupes=<slot>&frame=<thumb frame>[&color=6f7680]` (see e2e/avatar-harness/dupes.ts).
 */
export const HIDDEN: Partial<Record<Slot, readonly number[]>> = {
  // denim texture vs plain is invisible once a colour is picked; starter characters' picks are kept
  outer: [21],
  bottom: [0, 3, 13, 23, 30, 71, 80],
  shoes: [72, 75, 76],
  socks: [50, 60, 67, 92, 95, 98, 99],
  bag: [38],
  // Rose tint ≈ Gradient tint
  glasses: [4, 14, 24, 34, 54, 84, 94],
};

const sets = new Map<Slot, Set<number>>();
export function isHidden(slot: Slot, id: number): boolean {
  const list = HIDDEN[slot];
  if (!list) return false;
  let s = sets.get(slot);
  if (!s) sets.set(slot, (s = new Set(list)));
  return s.has(id);
}
